def guide_pages(c):
    out = []
    for g in GUIDES:
        path = f"/guide/{g['slug']}"
        crumbs = [("Forside", "/"), ("Guider", path), (g["crumb"], path)]
        crumbs = [("Forside", "/"), (g["crumb"], path)]
        secs = "".join(f'<h2 class="h-m" style="margin-top:28px">{h}</h2>' + "".join(f"<p>{p}</p>" for p in ps) for h, ps in g["sections"])
        links = "".join(f'<a class="textlink" href="{u}">{t}</a>' for u, t in g["links"])
        body = f'''<div class="wrap case-hero" style="max-width:840px">
  {c["crumbs_html"](crumbs)}
  <span class="eyebrow">{g["eyebrow"]}</span>
  <h1 class="h-xl">{g["h1"]}</h1>
  <p class="lede">{g["lede"]}</p>
</div>
<section class="section tight" style="padding-top:0"><div class="wrap" style="max-width:840px">
  <div class="prose">{secs}</div>
  <div class="btns" style="margin-top:32px;gap:20px;flex-wrap:wrap">{links}</div>
</div></section>
{c["cta_band"](title="Vil du ha en fast pris?", text="Fortell kort om bedriften din, så får du et tilbud innen én arbeidsdag.")}'''
        out.append(dict(path=path, id="guide-" + g["slug"], title=g["title"], desc=g["desc"], body=body, ld=[c["breadcrumbs_ld"](crumbs)]))
    return out
